import React, { ElementType } from 'react';
import { ParagraphProps } from './ParagraphTypes';
import { Text } from './Paragraph.styles';

const DEFAULT_TAG = 'p' as ElementType;

const Paragraph = React.forwardRef(
  (
    {
      size = 'basis',
      colortype = 'primary',
      foreground = 'false',
      alignment = 'left',
      weight = 'normal',
      selectable = 'true',
      children,
      css,
      ...props
    }: Omit<ParagraphProps, 'as'>,
    forwardedRef: React.ForwardedRef<HTMLParagraphElement>
  ): JSX.Element => (
    <Text
      as={DEFAULT_TAG}
      size={size}
      colortype={colortype}
      alignment={alignment}
      foreground={foreground}
      weight={weight}
      selectable={selectable}
      ref={forwardedRef}
      css={css}
      {...props}
    >
      {children}
    </Text>
  )
);

export default Paragraph;
